AssistantMessageToolRequest(name='create', tool_call_id='tooluse_F7s0hLKytK4Rj7QTl5H83y', arguments={'file_text': "const form = document.getElementById('contactForm');
const fullNameInput = document.getElementById('fullName');
const emailInput = document.getElementById('email');
const phoneInput = document.getElementById('phone');
const successMessage = document.getElementById('successMessage');

const fullNameError = document.getElementById('fullName-error');
const emailError = document.getElementById('email-error');
const phoneError = document.getElementById('phone-error');

// Validation rules
function validateFullName(value) {
  if (!value.trim()) {
    return 'Error: Please enter your full name.';
  }
  if (value.trim().length < 2) {
    return 'Error: Full name must be at least 2 characters.';
  }
  return '';
}

function validateEmail(value) {
  if (!value.trim()) {
    return 'Error: Please enter your email address.';
  }
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(value)) {
    return 'Error: Please enter a valid email address.';
  }
  return '';
}

function validatePhone(value) {
  // Phone is optional, but if provided, validate format
  if (!value.trim()) {
    return '';
  }
  // Basic phone validation: should contain digits and common separators
  const phoneRegex = /^[+]?[(]?[0-9]{3}[)]?[-\s.]?[0-9]{3}[-\s.]?[0-9]{4}$/;
  if (!phoneRegex.test(value.replace(/\s/g, ''))) {
    return 'Error: Please enter a valid phone number.';
  }
  return '';
}

function clearFieldError(input, errorElement) {
  input.removeAttribute('aria-invalid');
  errorElement.textContent = '';
}

function setFieldError(input, errorElement, message) {
  input.setAttribute('aria-invalid', 'true');
  errorElement.textContent = message;
}

function validateField(input, errorElement, validationFn) {
  const error = validationFn(input.value);
  if (error) {
    setFieldError(input, errorElement, error);
    return false;
  } else {
    clearFieldError(input, errorElement);
    return true;
  }
}

// Real-time validation (after user interacts)
fullNameInput.addEventListener('blur', () => {
  validateField(fullNameInput, fullNameError, validateFullName);
});

emailInput.addEventListener('blur', () => {
  validateField(emailInput, emailError, validateEmail);
});

phoneInput.addEventListener('blur', () => {
  validateField(phoneInput, phoneError, validatePhone);
});

// Form submission
form.addEventListener('submit', (e) => {
  e.preventDefault();

  // Validate all fields
  const isFullNameValid = validateField(fullNameInput, fullNameError, validateFullName);
  const isEmailValid = validateField(emailInput, emailError, validateEmail);
  const isPhoneValid = validateField(phoneInput, phoneError, validatePhone);

  if (isFullNameValid && isEmailValid && isPhoneValid) {
    // All fields are valid
    successMessage.hidden = false;
    successMessage.focus();

    // Reset form after showing success
    setTimeout(() => {
      form.reset();
      successMessage.hidden = true;
      fullNameInput.focus();
    }, 3000);
  } else {
    // Focus on the first invalid field
    if (!isFullNameValid) {
      fullNameInput.focus();
    } else if (!isEmailValid) {
      emailInput.focus();
    } else if (!isPhoneValid) {
      phoneInput.focus();
    }
  }
});
