  max-width: 500px;
}

h1 {
  font-size: 2rem;
  margin-bottom: 12px;
  color: #ffffff;
}

.intro {
  color: #b0b0b0;
  margin-bottom: 32px;
  font-size: 0.95rem;
}

form {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

label {
  font-weight: 500;
  color: #e0e0e0;
  font-size: 0.95rem;
}

.required-marker {
  color: #ff6b6b;
  margin-left: 2px;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
  padding: 12px 14px;
  border: 1px solid #404040;
  border-radius: 6px;
  background-color: #2a2a2a;
  color: #e0e0e0;
  font-size: 1rem;
  transition: border-color 0.2s, box-shadow 0.2s;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus {
  outline: none;
  border-color: #6b9eff;
  box-shadow: 0 0 0 3px rgba(107, 158, 255, 0.15);
}

input:disabled {
  background-color: #1a1a1a;
  color: #808080;
  cursor: not-allowed;
}

input[aria-invalid="true"] {
  border-color: #ff6b6b;
}

input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(255, 107, 107, 0.15);
}

.help-text {
  font-size: 0.85rem;
  color: #909090;
  margin: 0;
}

.error-message {
  font-size: 0.85rem;
  color: #ff6b6b;
  margin: 0;
  display: none;
}

.error-message:not(:empty) {
  display: block;
}

.submit-button {
  padding: 12px 24px;
  border: none;
  border-radius: 6px;
  background-color: #6b9eff;
  color: #ffffff;
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: background-color 0.2s, box-shadow 0.2s;
  margin-top: 8px;
}

.submit-button:hover:not(:disabled) {
  background-color: #5a8fd9;
}

.submit-button:focus {
  outline: none;
  box-shadow: 0 0 0 3px rgba(107, 158, 255, 0.4);
}

.submit-button:active:not(:disabled) {
  background-color: #4a7fc0;
}

.submit-button:disabled {
  background-color: #505050;
  color: #808080;
  cursor: not-allowed;
}

.success-message {
  padding: 16px 20px;
  border-radius: 6px;
  background-color: #2a5f3a;
  color: #a8e6b8;
  border: 1px solid #3d7d4d;
  margin-top: 24px;
}

.success-message p {
  margin: 0;
  font-size: 0.95rem;
}

/* Responsive design */
@media (max-width: 640px) {
  body {
    padding: 16px;
  }

  h1 {
    font-size: 1.5rem;
  }

  .container {
    max-width: 100%;
  }
}

/* High contrast / Forced colors support */
@media (prefers-contrast: more) {
  input[type="text"],
  input[type="email"],
  input[type="tel"] {
    border-width: 2px;
  }

  .submit-button {
    border: 2px solid #6b9eff;
  }
}

@media (forced-colors: active) {
  input[type="text"],
  input[type="email"],
  input[type="tel"] {
    border-color: CanvasText;
    background-color: Canvas;
    color: CanvasText;
  }

  input[aria-invalid="true"] {
    border-color: Mark;
  }

  .submit-button {
    background-color: ButtonFace;
    color: ButtonText;
    border: 1px solid ButtonBorder;
  }

  .success-message {
    background-color: Canvas;
    border-color: CanvasText;
    color: CanvasText;
  }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  input[type="text"],
  input[type="email"],
  input[type="tel"],
  .submit-button {
    transition: none;
  }
}
